import os
import subprocess
import sys
import difflib

base_ref = os.environ['BASE']
upstream_ref = os.environ['UPSTREAM_REF']

def git_show(ref, path):
    return subprocess.check_output(
        ['git', 'show', f'{ref}:{path}']
    ).decode('utf-8', 'surrogateescape').splitlines(keepends=True)

def git_show_optional(ref, path):
    try:
        return git_show(ref, path)
    except subprocess.CalledProcessError:
        return []

def find_seq(lines, seq, start=0, end=None):
    if not seq:
        return -1
    n = len(seq)
    if end is None:
        end = len(lines)
    for i in range(start, end - n + 1):
        if lines[i:i+n] == seq:
            return i
    return -1

def find_insert_index(local, after, before):
    for k in range(min(5, len(after)), 0, -1):
        idx = find_seq(local, after[:k])
        if idx != -1:
            return idx
    for k in range(min(5, len(before)), 0, -1):
        seq = before[-k:]
        idx = -1
        for i in range(len(local) - len(seq) + 1):
            if local[i:i+len(seq)] == seq:
                idx = i
        if idx != -1:
            return idx + len(seq)
    for i in range(len(local) - 1, -1, -1):
        if local[i].strip() in (']', '}', ')'):
            return i
    return len(local)

raw = subprocess.check_output(
    ['git', 'diff', '--name-only', '--diff-filter=U', '-z']
)
paths = [p for p in raw.decode('utf-8', 'surrogateescape').split('\0') if p]

for path in paths:
    base = git_show_optional(base_ref, path)
    upstream = git_show_optional(upstream_ref, path)
    local = git_show_optional('HEAD', path)

    sm = difflib.SequenceMatcher(None, base, upstream, autojunk=False)
    targets = []
    local_set = set(local)
    for tag, i1, i2, j1, j2 in sm.get_opcodes():
        if tag != 'insert':
            continue
        inserted = upstream[j1:j2]
        after = upstream[j2:j2+5]
        before = upstream[max(0, j1-5):j1]
        missing = []
        seen = set()
        for line in inserted:
            if line not in local_set and line not in seen:
                missing.append(line)
                seen.add(line)
        if missing:
            idx = find_insert_index(local, after, before)
            targets.append((idx, missing))

    groups = {}
    for idx, lines in targets:
        groups.setdefault(idx, []).extend(lines)
    for idx in sorted(groups, reverse=True):
        local[idx:idx] = groups[idx]

    with open(path, 'w', encoding='utf-8', errors='surrogateescape') as f:
        f.writelines(local)
    subprocess.check_call(['git', 'add', '--', path])
